using Microsoft.VisualStudio.TestTools.UnitTesting;
using Commerce;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem Tests ---

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _cart.AddItem("SKU-001", 9.99m, 1);
        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesPrice()
    {
        _cart.AddItem("SKU-001", 5.00m, 3);
        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDifferentItems_SumsCorrectly()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 20.00m, 2);
        Assert.AreEqual(50.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_BothEntriesCounted()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.AddItem("SKU-001", 5.00m, 2);
        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrue()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        Assert.IsTrue(_cart.RemoveItem("SKU-001"));
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_DecreasesTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 5.00m, 1);
        _cart.RemoveItem("SKU-001");
        Assert.AreEqual(5.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistingSku_ReturnsFalse()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        Assert.IsFalse(_cart.RemoveItem("SKU-999"));
    }

    [TestMethod]
    public void RemoveItem_RemovesAllEntriesWithSameSku()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.AddItem("SKU-001", 5.00m, 2);
        _cart.RemoveItem("SKU-001");
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    // --- GetTotal Tests ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterAddAndRemove_ReturnsCorrectTotal()
    {
        _cart.AddItem("SKU-001", 25.00m, 2);
        _cart.AddItem("SKU-002", 10.00m, 1);
        _cart.RemoveItem("SKU-002");
        Assert.AreEqual(50.00m, _cart.GetTotal());
    }

    // --- ApplyPromoCode Tests ---

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReducesTotal()
    {
        _cart.AddItem("SKU-001", 100.00m, 1);
        bool applied = _cart.ApplyPromoCode("SAVE10");
        Assert.IsTrue(applied);
        Assert.AreEqual(90.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        _cart.AddItem("SKU-001", 100.00m, 1);
        bool applied = _cart.ApplyPromoCode("BOGUS");
        Assert.IsFalse(applied);
        Assert.AreEqual(100.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_DiscountCannotExceedTotal()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.ApplyPromoCode("SAVE10");
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }
}

